observation.command:
cd /workspace && cat > /tmp/launch-app2.mjs <<'EOF'
import { spawn } from 'node:child_process';
import { openSync } from 'node:fs';
import { buildProfileEnv } from '/workspace/scripts/ops/runtime/profile-env.ts';

const env = buildProfileEnv('local-builder', { rootDir: '/workspace' });
env.NX_DAEMON = 'false';
env.NO_COLOR = '1';

const logFd = openSync('/tmp/app-serve2.log', 'a');
const child = spawn('pnpm', ['nx', 'run', 'sva-studio-react:serve'], {
  cwd: '/workspace',
  env,
  stdio: ['ignore', logFd, logFd],
  detached: true,
});
child.unref();
console.log('launched dev server pid', child.pid);
EOF
rm -f /tmp/app-serve2.log
nohup pnpm exec tsx /tmp/launch-app2.mjs > /tmp/launch2.log 2>&1 &
sleep 4; cat /tmp/launch2.log
